pub async fn detect_causal_gaps(&self, failed_tasks: &[TaskRecord]) -> Result<Vec<CausalGap>> {
    let prompt = build_causal_analysis_prompt(failed_tasks);
    let response = self.llm_client.chat_with_schema(
        &prompt,
        &CAUSAL_ANALYSIS_SCHEMA
    ).await?;
    let analysis: CausalAnalysis = serde_json::from_str(&response)?;
    Ok(analysis.identified_gaps)
}

