pub async fn select_evolution_action(&self, state: &EvolutionState) -> Result<EvolutionAction> {
    let prompt = build_strategy_prompt(state, self.history);
    let mut action: Option<EvolutionAction> = None;

    for attempt in 0..3 {
        let response = self.llm_client.chat_with_schema(&prompt, &ACTION_SCHEMA).await?;
        let candidate: EvolutionAction = serde_json::from_str(&response)?;

        if self.validator.validate(&candidate, state) {
            action = Some(candidate);
            break;
        }
    }

    Ok(action.ok_or("Failed to generate valid action")?)
}

pub async fn negotiate(&self, state: &EvolutionState) -> Result<EvolutionAction> {
    // Round 1: 独立分析
    let creator_proposal = self.creator.analyze(state).await?;
    let optimizer_proposal = self.optimizer.analyze(state).await?;
    let eliminator_proposal = self.eliminator.analyze(state).await?;

    // Round 2: 互相评论
    let critiques = self.collect_critiques(&proposals).await?;

    // Round 3: Planner 决策
    let decision = self.planner.decide(&proposals, &critiques).await?;

    // Round 4: 投票确认
    let votes = self.collect_votes(&decision).await?;

    if votes.approval_rate > 0.6 {
        Ok(decision)
    } else {
        Err("Consensus not reached")
    }
}

