pub async fn generate_tool(&self, spec: &ToolSpec) -> Result<GeneratedCode> {
    let examples = self.example_db.retrieve_similar(spec, 3)?;
    let prompt = build_codegen_prompt(spec, &examples);

    let mut code = self.llm_client.chat(&prompt).await?;

    for attempt in 0..5 {
        match self.compile_check(&code).await {
            Ok(()) => return Ok(GeneratedCode { code, compiled: true }),
            Err(errors) => {
                let fix_prompt = build_fix_prompt(&code, &errors);
                code = self.llm_client.chat(&fix_prompt).await?;
            }
        }
    }

    Err("Failed to generate compilable code")
}
